sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({
    api,
    helpers
}) {
    if (!api.data.record.form || !api.data.record.form.fields) return true;
    var consumer = api.data.record.form.fields.consumer;
    var contact = api.data.record.form.fields.contact;
    var isNew = api.data.record.isNew;
    if (isNew)
        return true;
    else if (!contact || !contact.dictionary.canRead)
        return true;
    else if (consumer && consumer.value != "" && contact.value == "")
        return true;
    else
        return false;
}
